def contains_quad(g,wire,quad):
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);count=c._count(g,wire)
    a=c._vec(g,g.position())
    z=c._vec(g,c._sample(g,wire,g.position(),g.math('MODULO',i+1.,g.math('MAXIMUM',count,1.)),'FLOAT_VECTOR'))
    edges=[c._sub(quad[(j+1)%4],quad[j]) for j in range(4)]
    enter=0.;leave=1.;possible=1.;convex=1.
    for j,(p,e) in enumerate(zip(quad,edges)):
        length=c._length(g,e);convex=convex*g.math('GREATER_THAN',length,1e-8)
        convex=convex*g.math('GREATER_THAN',c._cross(e,edges[(j+1)%4]),1e-12)
        x=c._cross(e,c._sub(a,p))/g.math('MAXIMUM',length,1e-12)
        y=c._cross(e,c._sub(z,p))/g.math('MAXIMUM',length,1e-12);delta=y-x
        parallel=g.math('LESS_THAN',g.math('ABSOLUTE',delta),1e-10)
        hit=(1e-5-x)/delta
        enter=g.math('MAXIMUM',enter,c.choose(g,(1.-parallel)*g.math('GREATER_THAN',delta,0.),hit,-1e20))
        leave=g.math('MINIMUM',leave,c.choose(g,(1.-parallel)*g.math('LESS_THAN',delta,0.),hit,1e20))
        possible=possible*c.choose(g,parallel,g.math('GREATER_THAN',x,1e-5),1.)
    intrudes=possible*g.math('GREATER_THAN',leave,enter+1e-8)
    centre=[sum(p[axis] for p in quad)*.25 for axis in (0,1)]
    straddles=g.math('ABSOLUTE',g.math('GREATER_THAN',a[1],centre[1])-g.math('GREATER_THAN',z[1],centre[1]))
    hit=a[0]+(centre[1]-a[1])*(z[0]-a[0])/(z[1]-a[1])
    hits=c._stat(g,wire,straddles*g.math('GREATER_THAN',hit,centre[0]),'Sum')
    return convex*g.math('LESS_THAN',c._stat(g,wire,intrudes,'Sum'),.5)*g.math('COMPARE',g.math('MODULO',hits,2.),1.)


def _side(g,path,wire,steps,step,length,offset,cell,reverse,*,interpolation=False):
    """A straight station curve carries the piecewise-linear XY as its value."""
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);nw=c._count(g,wire)
