    candidates=c._select(g,candidates,flagged*g.math('COMPARE',c._read(g,approaches,'st_pp_reverse',mid,'INT'),0.))
    ri=g.node('GeometryNodeRepeatInput','Once per complete internal Street')
    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro);ro.repeat_items.clear()
    for kind,key in (('GEOMETRY','Ribbons'),('GEOMETRY','Status'),('BOOLEAN','Valid')):ro.repeat_items.new(kind,key)
    valid=c.V(g,inp.outputs['Input Valid'])*g.math('COMPARE',c._stat(g,steps,flagged,'Sum'),2.*c._count(g,candidates))
    g.bind(valid,ri.inputs['Valid'])
    g.bind(c.choose(g,valid,c._count(g,candidates),0,'INT'),ri.inputs['Iterations'])
    step=c._read(g,candidates,'_cf_step',ri.outputs['Iteration'],'INT');span=c._read(g,steps,'st_lq_span',step,'INT')
    same=flagged*g.math('COMPARE',c.named(g,'st_lq_span','INT'),span)
    reverse=c._read(g,approaches,'st_pp_reverse',c.named(g,'st_lq_mid_a','INT'),'INT')
    opposite=c._stat(g,steps,i*same*reverse,'Sum')
    pair_ok=g.math('COMPARE',c._stat(g,steps,same,'Sum'),2.)*g.math('COMPARE',c._stat(g,steps,same*reverse,'Sum'),1.)
    a=c._read(g,steps,'st_lq_mid_a',step,'INT');z=c._read(g,steps,'st_lq_mid_a',opposite,'INT')
    pair_ok=pair_ok*g.math('COMPARE',c._read(g,approaches,'st_cj_weighted',a,'BOOLEAN'),c._read(g,approaches,'st_cj_weighted',z,'BOOLEAN'))
    source=g.node('GeometryNodeGroup');source.node_tree=ports.approach(interpolation=interpolation)
    for key in ('Sources','Mapping','Approaches'):g.bind(inp.outputs[key],source.inputs[key])
    g.bind(a,source.inputs['Index']);path=source.outputs['Geometry'];length=c.V(g,source.outputs['Length'])
    width=c.V(g,source.outputs['Width']);offset=c.V(g,source.outputs['Offset']);cell=g.math('MAXIMUM',inp.outputs['Cell Size'],.02)
    left,left_ok,left_details=_side(g,path,wire,steps,opposite,length,offset-.5*width,cell,True,interpolation=interpolation)
    right,right_ok,right_details=_side(g,path,wire,steps,step,length,offset+.5*width,cell,False,interpolation=interpolation)
    right,aligned_ok=_align_stations(g,left,right)
    stations=b._join(g,left,right);sort=g.node('GeometryNodeSortElements');sort.domain='POINT'
    g.bind(stations,sort.inputs['Geometry']);g.bind(g.separate(g.position())[0],sort.inputs['Sort Weight']);stations=sort.outputs['Geometry']
    s=g.separate(g.position())[0];previous=g.separate(c._sample(g,stations,g.position(),g.math('MAXIMUM',i-1.,0.),'FLOAT_VECTOR'))[0]
    stations=c._select(g,stations,g.math('MAXIMUM',g.math('LESS_THAN',i,.5),g.math('GREATER_THAN',s,previous)))
    count=c._count(g,stations);s=c._vec(g,c._sample(g,stations,g.position(),i,'FLOAT_VECTOR'))[0]
    t=c._vec(g,c._sample(g,stations,g.position(),i+1.,'FLOAT_VECTOR'))[0]
    cells=c._line(g,g.math('MAXIMUM',count-1.,1.))
    for key,point in zip('abcd',(_sample_side(g,right,s),_sample_side(g,right,t),_sample_side(g,left,t),_sample_side(g,left,s))):
        cells=c._store(g,cells,'_cf_'+key,g.xyz(*point),'FLOAT_VECTOR')
    cells=c._store(g,cells,'_cf_station',s);cells=c._store(g,cells,'_cf_end',t)
